# 多租户特性开关存储。tenant 与 flag 均为 [a-z0-9_] 字符串。


class FeatureFlagStore:
    def __init__(self):
        self._flags = {}

    @staticmethod
    def _key(tenant, flag):
        # 错误：直接拼接，不同 (tenant, flag) 组合会映射到同一字符串。
        return tenant + flag

    def set_flag(self, tenant, flag, enabled):
        self._flags[FeatureFlagStore._key(tenant, flag)] = bool(enabled)

    def is_enabled(self, tenant, flag):
        return self._flags.get(FeatureFlagStore._key(tenant, flag), False)

    def clear(self, tenant, flag):
        self._flags.pop(FeatureFlagStore._key(tenant, flag), None)

